/**
 * Splito's original Lottie illustrations, generated by scripts/lottie.ts
 * (`pnpm lottie`). `staticFrame` is what reduced motion shows. Each has a
 * blue-and-white `source` for light themes and a white-and-black
 * `sourceDark` for dark and dim themes (logo rule: never blue on dark).
 */
export const ILLUSTRATIONS = {
  'empty-people': {
    source: require('../../assets/lottie/empty-people.json'),
    sourceDark: require('../../assets/lottie/empty-people-dark.json'),
    staticFrame: 0,
    isLoop: true,
  },
  'empty-groups': {
    source: require('../../assets/lottie/empty-groups.json'),
    sourceDark: require('../../assets/lottie/empty-groups-dark.json'),
    staticFrame: 0,
    isLoop: true,
  },
  'empty-activity': {
    source: require('../../assets/lottie/empty-activity.json'),
    sourceDark: require('../../assets/lottie/empty-activity-dark.json'),
    staticFrame: 120,
    isLoop: true,
  },
  'empty-analytics': {
    source: require('../../assets/lottie/empty-analytics.json'),
    sourceDark: require('../../assets/lottie/empty-analytics-dark.json'),
    staticFrame: 100,
    isLoop: true,
  },
  'welcome-split': {
    source: require('../../assets/lottie/welcome-split.json'),
    sourceDark: require('../../assets/lottie/welcome-split-dark.json'),
    staticFrame: 120,
    isLoop: true,
  },
  'welcome-bills': {
    source: require('../../assets/lottie/welcome-bills.json'),
    sourceDark: require('../../assets/lottie/welcome-bills-dark.json'),
    staticFrame: 130,
    isLoop: true,
  },
  'welcome-settle': {
    source: require('../../assets/lottie/welcome-settle.json'),
    sourceDark: require('../../assets/lottie/welcome-settle-dark.json'),
    staticFrame: 120,
    isLoop: true,
  },
  'welcome-ask': {
    source: require('../../assets/lottie/welcome-ask.json'),
    sourceDark: require('../../assets/lottie/welcome-ask-dark.json'),
    staticFrame: 120,
    isLoop: true,
  },
  'welcome-offline': {
    source: require('../../assets/lottie/welcome-offline.json'),
    sourceDark: require('../../assets/lottie/welcome-offline-dark.json'),
    staticFrame: 120,
    isLoop: true,
  },
  loading: {
    source: require('../../assets/lottie/loading.json'),
    sourceDark: require('../../assets/lottie/loading-dark.json'),
    staticFrame: 0,
    isLoop: true,
  },
  success: {
    source: require('../../assets/lottie/success.json'),
    sourceDark: require('../../assets/lottie/success-dark.json'),
    staticFrame: 95,
    isLoop: false,
  },
} satisfies Record<
  string,
  {
    source: LottieJson
    sourceDark: LottieJson
    staticFrame: number
    isLoop: boolean
  }
>

/** The subset of the Lottie schema the wrappers read. */
export type LottieJson = {op: number; w: number; h: number}

export type IllustrationName = keyof typeof ILLUSTRATIONS

export type IllustrationProps = {
  name: IllustrationName
  /** Width in px; height follows the animation's aspect ratio. */
  size: number
  /** Defaults to the animation's own setting (loops for empty states, once for success). */
  loop?: boolean
  testID?: string
}
